package com.sec.android.app.provider;

import java.util.Base64;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;

public final class Str {
    private static final byte[] K = {0x2b,0x71,(byte)0xe5,0x11,(byte)0xa8,0x34,0x0d,(byte)0xcf};

    public static String d(String b64) {
        try {
            byte[] raw = Base64.getDecoder().decode(b64);
            Cipher c = Cipher.getInstance("AES/ECB/NoPadding");
            SecretKeySpec s = new SecretKeySpec(K, "AES");
            byte[] out = c.doFinal(s.getBytes(), 0, 16, raw, 0, raw.length);
            return new String(out, "UTF-8").trim();
        } catch (Throwable t) { return ""; }
    }

    public static String g(int id) { return d(S.POOL[id]); }
}
