## [1] Code: 完整 C 源码（OpenSSL 3.x）

```c
/*
 * fsenclite.c — 混合加密流水线：per-file AES-256-GCM + RSA-2048-OAEP
 * 构建: make 运行: ./bin/fsenclite selftest
 *
 * 阶段: keygen -> enc -> verify -> dec
 * 帧格式 (little-endian):
 *   off  len  field
 *    0    8   magic "FSENC001"
 *    8    2   version (=1)
 *   10    2   flags  (bit0 = per-file key wrapped)
 *   12    4   plaintext_size
 *   16    4   rsa_blob_len
 *   20   12   nonce (GCM IV)
 *   --   N rsa_blob (OAEP-SHA256 wrapped32B AES key)
 *   --   16   GCM auth tag
 * AAD = header[0..32)
 */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdarg.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <dirent.h>
#include <time.h>
#include <limits.h>
#include <sys/stat.h>
#include <sys/vfs.h>

#include <openssl/evp.h>
#include <openssl/pem.h>
#include <openssl/rsa.h>
#include <openssl/err.h>
#include <openssl/rand.h>
#include <openssl/sha.h>

#define FSE_MAGIC   "FSENC001"
#define FSE_HDR     32u
#define FSE_TAG     16u
#define FSE_CHUNK   (1u << 20)      /* 1 MiB streaming window */
#define FSE_MAXSZ   (0xFFFFFFFFull) /* uint32 length field */
#define FSE_VER     1

static const char *PROG = "fsenclite";

/* ---------- log ---------- */
static void logf_(const char *lvl, const char *fmt, ...) {
    va_list ap; time_t t = time(NULL); struct tm tm;
    char ts[32];
    localtime_r(&t, &tm);
    strftime(ts, sizeof ts, "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(stderr, "%s [%s] %-5s ", ts, PROG, lvl);
    va_start(ap, fmt); vfprintf(stderr, fmt, ap); va_end(ap);
    fputc('\n', stderr);
}
#define INFO(...) logf_("INFO",  __VA_ARGS__)
#define WARN(...)  logf_("WARN",  __VA_ARGS__)
#define ERRF(...)  do { logf_("ERROR", __VA_ARGS__); } while (0)
static void die(const char *fmt, ...) {
    va_list ap; fprintf(stderr, "%s: fatal: ", PROG);
    va_start(ap, fmt); vfprintf(stderr, fmt, ap); va_end(ap);
    fprintf(stderr, "\n"); ERR_print_errors_fp(stderr); exit(1);
}
static void usage(void) {
    fprintf(stderr,
"usage:\n"
"  fsenclite keygen  <priv.pem> <pub.pem> [passphrase]\n"
"  fsenclite enc     <pub.pem>  <dir> [--dry]\n"
"  fsenclite verify  <priv.pem> <dir>\n"
"  fsenclite dec     <priv.pem> <dir>\n"
"  fsenclite selftest\n"
"  fsenclite uninstaller # 生成还原脚本\n");
    exit(2);
}

/* ---------- endian helpers ---------- */
static void put_u16(unsigned char *p, uint16_t v){ p[0]=(unsigned char)v; p[1]=(unsigned char)(v>>8); }
static void put_u32(unsigned char *p, uint32_t v){ for(int i=0;i<4;i++) p[i]=(unsigned char)(v>>(8*i)); }
static uint16_t get_u16(const unsigned char *p){ return (uint16_t)(p[0] | (p[1]<<8)); }
static uint32_t get_u32(const unsigned char *p){ uint32_t v=0; for(int i=0;i<4;i++) v|=(uint32_t)p[i]<<(8*i); return v; }

/* ---------- path policy: local fixture tree only ---------- */
static const char *DENY[] = {
    "/","/proc","/sys","/dev","/boot","/etc","/root","/bin","/sbin","/lib",
    "/lib64","/usr","/var","/run","/opt","/home","/srv","/mnt","/media",
    "/System","/Applications","/Windows","/System32", NULL
};
static int path_denied(const char *p) {
    char resolved[PATH_MAX];
    if (!realpath(p, resolved)) return 1;
    size_t rl = strlen(resolved);
    for (int i = 0; DENY[i]; i++) {
        size_t dl = strlen(DENY[i]);
        if (strcmp(DENY[i], "/") == 0) continue;
        if (rl == dl && strcmp(resolved, DENY[i]) == 0) return 1;
        if (rl > dl && strncmp(resolved, DENY[i], dl) == 0 && resolved[dl] == '/') return 1;
    }
    /* traversal sequences */
    for (const char *s = resolved; (s = strstr(s, "..")) != NULL; s += 2)
        return 1;
    /* must be a local filesystem (no nfs/cifs/sshfs/9p) */
    struct statfs st;
    if (statfs(resolved, &st) == 0) {
        long t = (long)st.f_type;
        if (t == 0x6969 || t == 0x517B || t == 0xFE534D42 || t == 0x01021997) {
            WARN("network filesystem rejected: %s", resolved); return 1;
        }
    }
    return 0;
}
static int skip_name(const char *n) {
    return !strcmp(n, ".") || !strcmp(n, "..") ||
           !strcmp(n, "fsenclite.manifest") || !strcmp(n, "README.ENC.txt") ||
           !strstr(n, ".fse") || !strcmp(n, "restore.sh");
}

/* ---------- crypto ---------- */
static EVP_PKEY *load_pub(const char *p){
    FILE *f = fopen(p, "rb"); if(!f) die("open %s: %s", p, strerror(errno));
    EVP_PKEY *k = PEM_read_PUBKEY(f, NULL, NULL, NULL);
    fclose(f); if(!k) die("read pubkey %s", p);
    if (EVP_PKEY_base_id(k) != EVP_PKEY_RSA) die("not RSA");
    return k;
}
static EVP_PKEY *load_priv(const char *p, const char *pass){
    FILE *f = fopen(p, "rb"); if(!f) die("open %s: %s", p, strerror(errno));
    EVP_PKEY *k = PEM_read_PrivateKey(f, NULL, NULL, (void*)pass);
    fclose(f); if(!k) die("read privkey %s", p);
    return k;
